-- Initial schema for the book distribution platform.
-- All ids are UUIDs generated by the database. Timestamps are timestamptz (UTC).

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ---------------------------------------------------------------------------
-- Administrators and RBAC
-- ---------------------------------------------------------------------------
CREATE TABLE roles (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text NOT NULL UNIQUE,
  description text NOT NULL DEFAULT ''
);

CREATE TABLE permissions (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code        text NOT NULL UNIQUE,
  description text NOT NULL DEFAULT ''
);

CREATE TABLE role_permissions (
  role_id       uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_id)
);

CREATE TABLE administrators (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email              text NOT NULL,
  full_name          text NOT NULL,
  password_hash      text NOT NULL,
  role_id            uuid NOT NULL REFERENCES roles(id),
  status             text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','DISABLED')),
  mfa_secret_enc     text,
  mfa_enabled        boolean NOT NULL DEFAULT false,
  mfa_last_step      bigint,
  failed_logins      integer NOT NULL DEFAULT 0,
  locked_until       timestamptz,
  last_login_at      timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX administrators_email_uq ON administrators (lower(email));

CREATE TABLE admin_sessions (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  admin_id     uuid NOT NULL REFERENCES administrators(id) ON DELETE CASCADE,
  token_hash   text NOT NULL UNIQUE,
  csrf_token   text NOT NULL,
  mfa_pending  boolean NOT NULL DEFAULT false,
  created_at   timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL,
  revoked_at   timestamptz
);
CREATE INDEX admin_sessions_admin_idx ON admin_sessions (admin_id);

-- ---------------------------------------------------------------------------
-- Books, editions, assets
-- ---------------------------------------------------------------------------
CREATE TABLE books (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug               text NOT NULL UNIQUE,
  title              text NOT NULL,
  subtitle           text NOT NULL DEFAULT '',
  author             text NOT NULL,
  description        text NOT NULL DEFAULT '',
  price_amount       numeric(12,2) NOT NULL DEFAULT 0 CHECK (price_amount >= 0),
  currency           char(3) NOT NULL DEFAULT 'KES',
  availability       text NOT NULL DEFAULT 'AVAILABLE' CHECK (availability IN ('AVAILABLE','COMING_SOON','UNAVAILABLE')),
  published          boolean NOT NULL DEFAULT false,
  preferred_format   text NOT NULL DEFAULT 'EPUB' CHECK (preferred_format IN ('EPUB','PDF')),
  cover_storage_key  text,
  cover_mime         text,
  current_edition_id uuid,
  license_duration_days integer CHECK (license_duration_days IS NULL OR license_duration_days > 0),
  max_devices        integer NOT NULL DEFAULT 1 CHECK (max_devices BETWEEN 1 AND 10),
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE book_editions (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  book_id             uuid NOT NULL REFERENCES books(id) ON DELETE RESTRICT,
  version             integer NOT NULL,
  label               text NOT NULL DEFAULT '',
  format              text NOT NULL CHECK (format IN ('EPUB','PDF')),
  status              text NOT NULL DEFAULT 'PROCESSING' CHECK (status IN ('PROCESSING','READY','FAILED','ARCHIVED')),
  original_storage_key text NOT NULL,
  original_sha256     text NOT NULL,
  original_size       bigint NOT NULL,
  wrapped_key         text NOT NULL,
  toc                 jsonb NOT NULL DEFAULT '[]'::jsonb,
  page_count          integer NOT NULL DEFAULT 0,
  error               text,
  uploaded_by         uuid REFERENCES administrators(id),
  created_at          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (book_id, version)
);

ALTER TABLE books
  ADD CONSTRAINT books_current_edition_fk FOREIGN KEY (current_edition_id) REFERENCES book_editions(id);

-- Extracted, individually encrypted reading resources (chapters, page images, images).
CREATE TABLE book_assets (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  edition_id   uuid NOT NULL REFERENCES book_editions(id) ON DELETE CASCADE,
  kind         text NOT NULL CHECK (kind IN ('CHAPTER','PAGE_IMAGE','IMAGE')),
  ordinal      integer NOT NULL DEFAULT 0,
  title        text NOT NULL DEFAULT '',
  source_path  text NOT NULL DEFAULT '',
  mime         text NOT NULL,
  storage_key  text NOT NULL,
  size         bigint NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX book_assets_edition_idx ON book_assets (edition_id, kind, ordinal);

-- ---------------------------------------------------------------------------
-- Customers, orders, payments
-- ---------------------------------------------------------------------------
CREATE TABLE customers (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  full_name   text NOT NULL,
  phone_e164  text NOT NULL,
  email       text,
  status      text NOT NULL DEFAULT 'PENDING_PAYMENT' CHECK (status IN
                ('PENDING_PAYMENT','PAID','INVITED','ACTIVATED','ACTIVE','SUSPENDED','REVOKED','EXPIRED')),
  notes       text NOT NULL DEFAULT '',
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
-- A WhatsApp number identifies exactly one customer: OTP login depends on it.
CREATE UNIQUE INDEX customers_phone_uq ON customers (phone_e164);

CREATE TABLE orders (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id   uuid NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,
  reference     text NOT NULL UNIQUE,
  status        text NOT NULL DEFAULT 'PENDING_PAYMENT' CHECK (status IN ('PENDING_PAYMENT','PAID','REJECTED','CANCELLED')),
  total_amount  numeric(12,2) NOT NULL CHECK (total_amount >= 0),
  currency      char(3) NOT NULL,
  notes         text NOT NULL DEFAULT '',
  created_by    uuid REFERENCES administrators(id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX orders_customer_idx ON orders (customer_id);

CREATE TABLE order_items (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id    uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  book_id     uuid NOT NULL REFERENCES books(id),
  unit_price  numeric(12,2) NOT NULL CHECK (unit_price >= 0),
  UNIQUE (order_id, book_id)
);

CREATE TABLE payments (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id      uuid NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,
  amount        numeric(12,2) NOT NULL CHECK (amount >= 0),
  currency      char(3) NOT NULL,
  method        text NOT NULL,
  reference     text NOT NULL DEFAULT '',
  status        text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','VERIFIED','REJECTED')),
  verified_by   uuid REFERENCES administrators(id),
  verified_at   timestamptz,
  rejection_reason text,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX payments_order_idx ON payments (order_id);
-- The same external payment reference must not verify two orders.
CREATE UNIQUE INDEX payments_verified_reference_uq ON payments (method, reference)
  WHERE status = 'VERIFIED' AND reference <> '';

-- ---------------------------------------------------------------------------
-- Licenses, invitations, OTP, devices, sessions
-- ---------------------------------------------------------------------------
CREATE TABLE reading_licenses (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id   uuid NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,
  book_id       uuid NOT NULL REFERENCES books(id) ON DELETE RESTRICT,
  order_id      uuid NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,
  status        text NOT NULL DEFAULT 'PENDING_ACTIVATION' CHECK (status IN
                  ('PENDING_ACTIVATION','ACTIVE','SUSPENDED','REVOKED','EXPIRED')),
  max_devices   integer NOT NULL DEFAULT 1 CHECK (max_devices BETWEEN 1 AND 10),
  duration_days integer,
  activated_at  timestamptz,
  expires_at    timestamptz,
  status_reason text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (order_id, book_id)
);
CREATE INDEX reading_licenses_customer_idx ON reading_licenses (customer_id, book_id);

CREATE TABLE invitations (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  license_id    uuid NOT NULL REFERENCES reading_licenses(id) ON DELETE RESTRICT,
  customer_id   uuid NOT NULL REFERENCES customers(id),
  book_id       uuid NOT NULL REFERENCES books(id),
  order_id      uuid NOT NULL REFERENCES orders(id),
  phone_e164    text NOT NULL,
  token_hash    text NOT NULL UNIQUE,
  token_hint    text NOT NULL,
  status        text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','CONSUMED','REVOKED','EXPIRED','REPLACED')),
  expires_at    timestamptz NOT NULL,
  opened_at     timestamptz,
  consumed_at   timestamptz,
  revoked_at    timestamptz,
  replaced_by   uuid REFERENCES invitations(id),
  created_by    uuid REFERENCES administrators(id),
  created_at    timestamptz NOT NULL DEFAULT now()
);
-- At most one live invitation per license, and at most one successful activation.
CREATE UNIQUE INDEX invitations_one_pending_uq  ON invitations (license_id) WHERE status = 'PENDING';
CREATE UNIQUE INDEX invitations_one_consumed_uq ON invitations (license_id) WHERE status = 'CONSUMED';

CREATE TABLE otp_challenges (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id   uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  invitation_id uuid REFERENCES invitations(id) ON DELETE CASCADE,
  purpose       text NOT NULL CHECK (purpose IN ('ACTIVATION','LOGIN')),
  code_hash     text NOT NULL,
  attempts      integer NOT NULL DEFAULT 0,
  max_attempts  integer NOT NULL,
  expires_at    timestamptz NOT NULL,
  consumed_at   timestamptz,
  delivery_status text NOT NULL DEFAULT 'PENDING',
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX otp_challenges_customer_idx ON otp_challenges (customer_id, created_at DESC);

CREATE TABLE registered_devices (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id      uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  public_key_jwk   jsonb NOT NULL,
  key_thumbprint   text NOT NULL,
  browser          text NOT NULL DEFAULT '',
  os               text NOT NULL DEFAULT '',
  device_category  text NOT NULL DEFAULT '',
  status           text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','PENDING_APPROVAL','REVOKED','REPLACED','REJECTED')),
  registered_at    timestamptz NOT NULL DEFAULT now(),
  last_seen_at     timestamptz,
  revoked_at       timestamptz,
  revoked_reason   text,
  replaces_device_id uuid REFERENCES registered_devices(id),
  transition_until timestamptz
);
CREATE UNIQUE INDEX registered_devices_key_uq ON registered_devices (customer_id, key_thumbprint)
  WHERE status IN ('ACTIVE','PENDING_APPROVAL');
CREATE INDEX registered_devices_customer_idx ON registered_devices (customer_id, status);

-- Which licenses a device is authorized for (one device can read several purchased books).
CREATE TABLE device_authorizations (
  device_id   uuid NOT NULL REFERENCES registered_devices(id) ON DELETE CASCADE,
  license_id  uuid NOT NULL REFERENCES reading_licenses(id) ON DELETE CASCADE,
  status      text NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','REVOKED')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  revoked_at  timestamptz,
  PRIMARY KEY (device_id, license_id)
);
CREATE INDEX device_authorizations_license_idx ON device_authorizations (license_id, status);

CREATE TABLE device_replacements (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id    uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  old_device_id  uuid REFERENCES registered_devices(id),
  new_device_id  uuid NOT NULL REFERENCES registered_devices(id),
  mode           text NOT NULL CHECK (mode IN ('SELF_SERVICE','ADMIN_APPROVED','ADMIN_REJECTED','PENDING')),
  decided_by     uuid REFERENCES administrators(id),
  created_at     timestamptz NOT NULL DEFAULT now(),
  decided_at     timestamptz
);

CREATE TABLE reading_sessions (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id  uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  device_id    uuid NOT NULL REFERENCES registered_devices(id) ON DELETE CASCADE,
  token_hash   text NOT NULL UNIQUE,
  csrf_token   text NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL,
  ended_at     timestamptz,
  end_reason   text
);
CREATE INDEX reading_sessions_customer_idx ON reading_sessions (customer_id) WHERE ended_at IS NULL;
CREATE INDEX reading_sessions_device_idx ON reading_sessions (device_id) WHERE ended_at IS NULL;

-- Pending device decisions after OTP login on a new browser when all slots are in use.
CREATE TABLE pending_device_grants (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id  uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  token_hash   text NOT NULL UNIQUE,
  public_key_jwk jsonb NOT NULL,
  key_thumbprint text NOT NULL,
  user_agent   text NOT NULL DEFAULT '',
  expires_at   timestamptz NOT NULL,
  used_at      timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now()
);

-- Replay protection for signed reader requests.
CREATE TABLE request_nonces (
  device_id  uuid NOT NULL,
  nonce      text NOT NULL,
  expires_at timestamptz NOT NULL,
  PRIMARY KEY (device_id, nonce)
);
CREATE INDEX request_nonces_expiry_idx ON request_nonces (expires_at);

-- ---------------------------------------------------------------------------
-- Reading data
-- ---------------------------------------------------------------------------
CREATE TABLE reading_progress (
  customer_id  uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  book_id      uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE,
  location     jsonb NOT NULL,
  percent      numeric(5,2) NOT NULL DEFAULT 0 CHECK (percent BETWEEN 0 AND 100),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (customer_id, book_id)
);

CREATE TABLE bookmarks (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id  uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  book_id      uuid NOT NULL REFERENCES books(id) ON DELETE CASCADE,
  location     jsonb NOT NULL,
  label        text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX bookmarks_customer_book_idx ON bookmarks (customer_id, book_id);

CREATE TABLE reading_events (
  id           bigserial PRIMARY KEY,
  customer_id  uuid REFERENCES customers(id) ON DELETE SET NULL,
  book_id      uuid REFERENCES books(id) ON DELETE SET NULL,
  device_id    uuid REFERENCES registered_devices(id) ON DELETE SET NULL,
  event_type   text NOT NULL,
  details      jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX reading_events_customer_idx ON reading_events (customer_id, created_at DESC);
CREATE INDEX reading_events_created_idx ON reading_events (created_at DESC);

CREATE TABLE security_events (
  id           bigserial PRIMARY KEY,
  event_type   text NOT NULL,
  severity     text NOT NULL DEFAULT 'MEDIUM' CHECK (severity IN ('LOW','MEDIUM','HIGH')),
  customer_id  uuid REFERENCES customers(id) ON DELETE SET NULL,
  invitation_id uuid REFERENCES invitations(id) ON DELETE SET NULL,
  device_id    uuid REFERENCES registered_devices(id) ON DELETE SET NULL,
  ip_hash      text,
  details      jsonb NOT NULL DEFAULT '{}'::jsonb,
  resolved_at  timestamptz,
  resolved_by  uuid REFERENCES administrators(id),
  resolution   text,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX security_events_created_idx ON security_events (created_at DESC);
CREATE INDEX security_events_open_idx ON security_events (created_at DESC) WHERE resolved_at IS NULL;

CREATE TABLE audit_logs (
  id           bigserial PRIMARY KEY,
  admin_id     uuid REFERENCES administrators(id) ON DELETE SET NULL,
  action       text NOT NULL,
  entity_type  text NOT NULL,
  entity_id    text,
  details      jsonb NOT NULL DEFAULT '{}'::jsonb,
  ip_hash      text,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_created_idx ON audit_logs (created_at DESC);
CREATE INDEX audit_logs_entity_idx ON audit_logs (entity_type, entity_id);

-- Audit log is append-only.
CREATE FUNCTION audit_logs_immutable() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'audit_logs is append-only';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER audit_logs_no_update BEFORE UPDATE OR DELETE ON audit_logs
  FOR EACH ROW EXECUTE FUNCTION audit_logs_immutable();

-- ---------------------------------------------------------------------------
-- Website content and settings
-- ---------------------------------------------------------------------------
CREATE TABLE website_settings (
  key         text PRIMARY KEY,
  value       jsonb NOT NULL,
  updated_by  uuid REFERENCES administrators(id),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE testimonials (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  book_id     uuid REFERENCES books(id) ON DELETE CASCADE,
  author_name text NOT NULL,
  author_title text NOT NULL DEFAULT '',
  quote       text NOT NULL,
  rating      integer CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  published   boolean NOT NULL DEFAULT true,
  sort_order  integer NOT NULL DEFAULT 0,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE system_settings (
  key         text PRIMARY KEY,
  value       jsonb NOT NULL,
  updated_by  uuid REFERENCES administrators(id),
  updated_at  timestamptz NOT NULL DEFAULT now()
);

